def add_vectors(a, b):
    if len(a) != len(b):
        raise ValueError("vectors must have the same length")
    return [x + y for x, y in zip(a, b)]


def scale_vector(c, v):
    return [c * x for x in v]


def lin_comb(a, v, b, w):
    return add_vectors(scale_vector(a, v), scale_vector(b, w))

