problems.solution:
def coords(p, b1, b2):
    d = b1[0] * b2[1] - b1[1] * b2[0]
    if abs(d) < 1e-9:
        raise ValueError("b1 and b2 do not form a basis")
    a = (p[0] * b2[1] - p[1] * b2[0]) / d
    b = (b1[0] * p[1] - b1[1] * p[0]) / d
    return (a, b)
